import assert from 'node:assert/strict';import {buildReticulation,relativeNeighbours,planarContacts} from '../src/reticulation.js';import {seeded} from '../src/geometry.js';
const rand=seeded(213),d2=(a,b)=>(a.x-b.x)**2+(a.y-b.y)**2;
for(let t=0;t<100;t++){const src={x:rand()*40,y:rand()*40},nodes=Array.from({length:70},()=>({x:rand()*80,y:rand()*80})),candidates=nodes.map((n,i)=>({i,d:d2(n,src)}));const brute=candidates.filter(v=>!candidates.some(u=>u.i!==v.i&&u.d<=v.d&&d2(nodes[v.i],nodes[u.i])<=v.d)).map(v=>v.i).sort((a,b)=>a-b);assert.deepEqual(relativeNeighbours(src,candidates,nodes).map(v=>v.i).sort((a,b)=>a-b),brute);}
const a=buildReticulation(),b=buildReticulation();assert.deepEqual(a.report,b.report);assert.deepEqual(a.nodes,b.nodes);assert.deepEqual(a.edges,b.edges);assert.equal(a.report.components,1);assert.equal(a.report.phases.length,3);assert.ok(a.report.cycles>1000);assert.ok(a.nodes.every(n=>Number.isFinite(n.x)&&Number.isFinite(n.y)));assert.ok(a.edges.every(e=>e.radius>0&&e.a!==e.b));const set=new Set(a.edges.map(e=>[Math.min(e.a,e.b),Math.max(e.a,e.b)].join(',')));assert.equal(set.size,a.edges.length);for(const order of [0,1,2,3,4])assert.ok(a.edges.some(e=>e.order===order));assert.equal(planarContacts(a.nodes,a.edges).crossings,0);console.log('PASS: 100 relative-neighbour comparisons, deterministic three-phase graph, connected actual cycles, five calibre orders, zero unjoined crossings');
